func processItems(items []string) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)
        for _, item := range items {
            out <- fmt.Sprintf("processed: %s", item)
        }
    }()
    return out
}

public List<String> filterActiveUsers(List<User> users) {
    return users.stream()
        .filter(u -> u.isActive() && u.getScore() > 50)
        .map(User::getUsername)
        .collect(Collectors.toList());
}

async function fetchUserPayload(userId) {
    try {
        const response = await fetch(`/api/v1/users/${userId}`);
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        return await response.json();
    } catch (err) {
        console.error("Failed to fetch user:", err);
    }
}

async def fetch_with_retry(url: str, retries: int = 3) -> dict:
    for attempt in range(retries):
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as resp:
                    return await resp.json()
        except aiohttp.ClientError as e:
            if attempt == retries - 1:
                raise RuntimeError(f"API request failed after {retries} attempts") from e

